param([string]$Root=(Resolve-Path (Join-Path $PSScriptRoot "..")).Path); $ErrorActionPreference="Stop"; $reg=Join-Path $Root "docs/security/ISSUE_63_CAPABILITY_EVIDENCE_REGISTER.json"; if(!(Test-Path $reg)){throw "Missing Issue #63 register: $reg"}; $d=Get-Content $reg -Raw|ConvertFrom-Json; $valid=@("Verified","Implemented but unverified","Simulator","Planned","External dependency","Prohibited or removed"); $req=@("claim","surface","status","evidence","automatedTest","owner","supportedDeviceScope","limitation"); $e=[System.Collections.Generic.List[string]]::new(); if([int]$d.issue -ne 63){$e.Add("Register issue must be 63.")}; foreach($c in @($d.claims)){foreach($f in $req){if([string]::IsNullOrWhiteSpace([string]$c.$f)){$e.Add("Register claim $($c.claim) missing $f.")}};if($valid -notcontains [string]$c.status){$e.Add("Register claim $($c.claim) has invalid status $($c.status).")};if([string]$c.status -eq "Verified" -and [string]$c.evidence -match "(?i)no |not |unverified|none|missing"){$e.Add("Register claim $($c.claim) is Verified without positive evidence.")}}; $roots=@("frontend/src/app","app","backend","system")|%{Join-Path $Root $_}|?{Test-Path $_}; $rx="(?i)SIG-KNOX|Knox certified|Samsung Knox|Knox Vault|hardware-backed attestation|fully certified|bootloader unlock|firmware flash|root access|bypass protection|warranty fuse|register modification"; foreach($r in $roots){foreach($f in Get-ChildItem $r -Recurse -File -Include *.cs,*.tsx,*.ts,*.js,*.jsx,*.html,*.kt,*.java,*.json){$n=0;foreach($line in Get-Content $f.FullName){$n++;if($line -match $rx -and $line -notmatch "(?i)does not provide|unavailable|unverified|emulator|simulates|simulated|planned"){$e.Add("Forbidden claim at ${f}:${n}: $($line.Trim())")}}}}; if($e.Count){$e|%{Write-Error $_};exit 1};Write-Output "Issue #63 claim lint passed: $(@($d.claims).Count) registered claims."

